func pillClass(status string) string {
	switch status {
	case "running":
		return "running"
	case "passed":
		return "done"
	case "failed":
		return "failed"
	default:
		return "queued"
	}
}

func truncate(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n-1] + "…"
}
